# چینش: مخلوط کردن دسته‌ها برای جلوگیری از الگوی تکراری
def interleave(qs,cats):
    by={c:[q for q in qs if q[0]==c] for c in cats}
    out=[]
    for i in range(max(len(v) for v in by.values())):
        for c in cats:
            if i<len(by[c]): out.append(by[c][i])
    return out
holland_q=interleave(holland_q,"RIASEC")

