TESTS=[
 (1,"holland-interest","تست علاقه‌ی شغلی هالند (RIASEC)","دوست داری بیشتر وقتت را با چه کاری بگذرانی؟ این تست بر پایه‌ی یکی از شناخته‌شده‌ترین مدل‌های علاقه‌ی شغلی (مدل هالند) طراحی شده و کمکت می‌کند بفهمی به کدام نوع فعالیت‌ها بیشتر گرایش داری؛ بعد بر همین اساس چند رشته و شغل هم‌راستا پیشنهاد می‌دهیم.","likert",10,"همه‌ی پایه‌ها","این تست از کجا آمده؟ از نظریه‌ی جان هالند درباره‌ی علاقه‌های شغلی الهام گرفته‌ایم؛ همان مدلی که پایه‌ی خیلی از تست‌های معتبر مشاوره‌ی شغلی در دنیاست. سؤال‌های این نسخه را خودمان نوشته‌ایم، پس آن را یک آزمون رسمی و استاندارد نگیر — بیشتر یک نقطه‌ی شروع خوب برای شناخت خودت و گفت‌وگو با دیگران است.","این نتیجه نشان می‌دهد به چه چیزهایی بیشتر علاقه داری، نه اینکه در چه کاری بهتری. برای یک تصمیم کامل‌تر، آن را کنار تست توانایی و ارزش‌های شغلی بگذار و اگر دوست داشتی با یک مشاور هم درباره‌اش حرف بزن.",holland_cats,holland_q,LIKERT_INTEREST),
 (2,"big-five-mini","تست شخصیت شغلی (پنج عامل بزرگ)","این تست کوتاه کمکت می‌کند بفهمی سبک کار و ارتباطت با دیگران چه شکلی است و در شرایط استرس‌زا معمولاً چطور رفتار می‌کنی.","likert",6,"از ۱۴ سال به بالا","این تست از کجا آمده؟ از نسخه‌ی کوتاه یک مدل شناخته‌شده در روان‌شناسی شخصیت (Mini-IPIP) الهام گرفته‌ایم. مهم است بدانی این ابزار تشخیصی یا روان‌پزشکی نیست؛ فقط یک ترجیح را نشان می‌دهد، نه خوب یا بد بودنت را. هیچ نمره‌ای اینجا نمره‌ی «قبولی» یا «مردودی» نیست.","شخصیتت راهت را محدود نمی‌کند؛ فقط نشان می‌دهد در کدام محیط‌ها راحت‌تری و برای کدام‌ها باید کمی بیشتر تمرین کنی.",b5_cats,b5_q,LIKERT_AGREE),
 (3,"multiple-intelligences","تست هوش‌های چندگانه (گاردنر)","هشت حوزه‌ی مختلف از توانمندی و علاقه وجود دارد؛ این تست کمکت می‌کند ببینی در کدام‌ها بیشتر احساس راحتی و لذت می‌کنی.","likert",8,"همه‌ی پایه‌ها","این تست از کجا آمده؟ از نظریه‌ی هوش‌های چندگانه‌ی هاوارد گاردنر گرفته شده. یک نکته‌ی مهم: پژوهشگران روان‌سنجی هنوز این نظریه را به‌عنوان یک ابزار دقیق اندازه‌گیری توانایی تأیید نکرده‌اند؛ برای همین بهتر است نتیجه را بیشتر برای شناخت علاقه‌هایت به کار ببری، نه اثبات توانایی واقعی‌ات.","این تست بیشتر نشان می‌دهد خودت را در چه حوزه‌هایی توانمندتر می‌بینی. برای سنجش دقیق‌تر توانایی واقعی‌ات، «تست استعداد و توانایی» و نمره‌های درسی‌ات را هم کنارش بگذار.",mi_cats,mi_q,LIKERT_AGREE),
 (4,"learning-preference","تست ترجیح یادگیری (الهام‌گرفته از مدل VARK)","بیشتر با دیدن یاد می‌گیری، با شنیدن، با نوشتن یا با انجام‌دادن؟ این تست کمکت می‌کند روش مطالعه‌ات را متنوع‌تر و لذت‌بخش‌تر کنی.","likert",5,"همه‌ی پایه‌ها","این تست از کجا آمده؟ از مدل VARK الهام گرفته شده، یکی از شناخته‌شده‌ترین مدل‌های سبک یادگیری. نکته‌ی جالب این است که پژوهش‌های جدی نتوانسته‌اند ثابت کنند محدودکردن مطالعه به «یک سبک» نتیجه‌ی بهتری می‌دهد. پس بهتر است از نتیجه‌ی این تست برای متنوع‌کردن روش مطالعه‌ات استفاده کنی، نه برای محدودکردن خودت به یک روش.","خبر خوب این است که بهترین روش‌های مطالعه برای همه یکسان‌اند: خودآزمایی، مرور در فاصله‌های زمانی، و تمرین متنوع. این تست فقط کمک می‌کند این روش‌ها را با ابزارهایی که بیشتر دوست داری انجام بدهی.",vk_cats,vk_q,LIKERT_AGREE),
 (5,"aptitude-basic","تست توانایی و استعداد تحصیلی پایه","۱۲ سؤال کوتاه که توانایی‌ات را در استدلال عددی، کلامی، منطقی و فضایی می‌سنجد. برخلاف تست‌های قبلی، اینجا هر سؤال یک پاسخ درست دارد.","ability",12,"از ۱۳ سال به بالا","این تست از کجا آمده؟ سؤال‌ها از سبک آزمون‌های استاندارد استعداد الگو گرفته شده‌اند، اما این نسخه کوتاه و آموزشی است، نه یک آزمون رسمی هنجاریابی‌شده. برای تصمیم‌های مهم، بهتر است از یک آزمون معتبر و نظر یک متخصص هم کمک بگیری.","چون تعداد سؤال‌ها کم است، تفاوت‌های کوچک بین دسته‌ها را زیاد جدی نگیر. خبر خوب این است که همه‌ی این توانایی‌ها با تمرین بهتر می‌شوند.",apt_cats,None,None),
 (6,"study-skills","تست مهارت‌های مطالعه و خودتنظیمی","می‌خواهی بدانی کدام عادت‌های مطالعه‌ات خوب جواب می‌دهد و کدامشان جای رشد دارد؟ این تست دقیقاً همین را نشان می‌دهد.","likert",7,"همه‌ی پایه‌ها","این تست از کجا آمده؟ بر پایه‌ی نظریه‌ی یادگیری خودتنظیم و پژوهش‌های شناخته‌شده درباره‌ی روش‌های مؤثر مطالعه طراحی شده. سؤال‌هایش را خودمان نوشته‌ایم، پس این یک پرسش‌نامه‌ی رسمی و استاندارد نیست.","دسته‌هایی که نمره‌ی پایین‌تری گرفته‌ای، جاهای خوبی برای شروع تمرین‌اند. لازم نیست همه را با هم درست کنی؛ روی یکی دو مورد تمرکز کن، همین کافی است.",st_cats,st_q,LIKERT_FREQ),
 (7,"major-readiness","تست آمادگی انتخاب رشته و مسیر شغلی","چقدر احساس آمادگی می‌کنی برای تصمیم‌گیری درباره‌ی رشته و شغلت؟ این تست نشان می‌دهد کدام بخش را باید بیشتر روی آن کار کنی.","likert",5,"دوره‌ی متوسطه","این تست از کجا آمده؟ از مفهوم «اعتماد به تصمیم‌گیری شغلی» در روان‌شناسی مشاوره الهام گرفته شده. سؤال‌هایش را خودمان طراحی کرده‌ایم.","نمره‌ی پایین در یک بخش فقط یعنی آنجا هنوز جای رشد داری، نه اینکه مسیرت اشتباه است. برای هر بخش یک قدم مشخص پیشنهاد داده‌ایم.",rd_cats,rd_q,LIKERT_AGREE),
 (8,"work-values","تست ارزش‌های شغلی","در یک شغل چه چیزی برایت بیشتر اهمیت دارد؟ استقلال، درآمد خوب، کمک به دیگران، امنیت شغلی یا پیشرفت و دیده‌شدن؟","likert",5,"همه‌ی پایه‌ها","این تست از کجا آمده؟ از دسته‌بندی ارزش‌های شغلی در سامانه‌ی معتبر O*NET الهام گرفته شده. سؤال‌هایش را خودمان نوشته‌ایم.","وقتی دو شغل به یک اندازه برایت جذاب‌اند، همین ارزش‌ها هستند که کمکت می‌کنند بین‌شان یکی را انتخاب کنی.",wv_cats,wv_q,LIKERT_AGREE),
]
